// src/mocks/handlers.js
import { http, HttpResponse } from "msw";
import { FRONT_BASE } from "../api/config";
// 어떤 URL로 치는지 + 응답 상태를 즉시 확인
(async () => {
  const { apiPath } = await import("/woodenpages/static/js/src_api_config_js.chunk.js").catch(()=>({apiPath:(x)=>x}));
  const url = apiPath ? apiPath("/order/orderlist") : "/order/orderlist";
  console.log("REQ URL = ", url);
  try {
    const r = await fetch(url);
    console.log("STATUS = ", r.status, "  FINAL_URL = ", r.url);
  } catch (e) {
    console.log("FETCH ERROR = ", e.message);
  }
})();

// 실제 SW 스코프에서 pathname 추출
const scopePathname =
// eslint-disable-next-line no-restricted-globals
  (typeof self !== "undefined" && self.registration && new URL(self.registration.scope).pathname) || "/";

const stripSlashEnd = (s) => s.replace(/\/$/, "");

// 프리픽스 3종 세트
const PREFIXES = [
  "",                                   // 절대경로
  stripSlashEnd(FRONT_BASE || "/"),     // /woodenpages
  stripSlashEnd(scopePathname || "/"),  // 실제 SW scope
];

// 모든 엔드포인트를 프리픽스 조합으로 등록
const paths = (p) => {
  const clean = p.startsWith("/") ? p : `/${p}`;
  return PREFIXES
    .map(pre => `${pre}${clean}`)
    // 중복 제거
    .filter((v, i, a) => a.indexOf(v) === i);
};

/** 3) in-memory seed */
const KEY = "WOODEN_MSW_DB_v1";
const seed = {
  // ORDER
  sellercustomer: [
    { cusNo: 1, cusComp: "판매처 A", cusName: "홍길동",
      cusEmail: "a@test.com", cusPhone: "010-1111-2222", cusAddr: "서울 강남구" }
  ],
  orderlist: [
    { orderNo: 1, orderDate: "2025-10-02", cusComp: "판매처 A",
      itemName: "완제품 A", orderQty: 19, orderPrice: 300000,
      orderState: "승인대기", orderDeliState: "납품대기",
      deliveryDate: "2025-10-24", cusAddr: "주소", totalPrice: 5700000 }
  ],
  completed: [],

  // BUYER
  buyercustomer: [
    { buyerNo: 1, buyerComp: "구매처 A", buyerName: "강감찬",
      buyerEmail: "a@buyer.com", buyerPhone: "010-5555-1111", buyerAddr: "대전 유성구" }
  ],
  partlist: [
    { partNo: 1, partCode: "01", partName: "부품 A",
      partSpec: "2*3*4", partPrice: 20000, buyerNo: 1 }
  ],
  partorder: [
    { poNo: 1, buyerNo: 1, buyerComp: "구매처 A", partNo: 1, partName: "부품 A",
      poQty: 50, poPrice: 3000, poState: "입고대기", poDate: "2025-10-01", buyerAddr: "대전 유성구" }
  ],
  // PLAN
  itemlist: [],
  planlist: [
    { planNo: 1, itemNo: 1, itemName: "완제품 A", planQty: 100,
      planState: "생산중", planStartDate: "2025-10-02", planEndDate: "2025-11-08" }
  ],
  bom: [{ bomId: 1, itemNo: 1, partNo: 1, qtyPerItem: 2 }],

  // STOCK
  itemstock: [
    { itemNo: 1, itemName: "완제품 A", isQty: 37, itemPrice: 15000,
      totalValue: 37 * 15000, lastUpdate: "2025-10-03" }
  ],
  partstocks: [
    { stockNo: 1, buyerComp: "구매처 A", partName: "부품 A",
      stockQty: 50, partPrice: 3000, lastInDate: "2025-10-01" }
  ],

  plancompleted: [],
  seq: { cusNo: 1, orderNo: 1, itemNo: 1, buyerNo: 1, bomId: 1, partNo: 1, poNo: 1, stockNo: 1, planNo: 1 }
};

/** 4) 로컬스토리지 DB 유틸 */
const load = () => {
  try { return JSON.parse(localStorage.getItem(KEY)) || seed; }
  catch { return seed; }
};
const save = (db) => {
  localStorage.setItem(KEY, JSON.stringify(db));
  return db;
}
const table = (name) => (load()[name] || []);
const setTable = (name, rows) => { const db = load(); db[name] = rows; return save(db)[name]; };
const nextId = (field) => { const db = load(); db.seq[field] = (db.seq[field] || 0) + 1; return save(db).seq[field]; };
const upsert = (name, row, pk) => {
  const rows = table(name);
  if (!row[pk]) row[pk] = nextId(pk);
  const i = rows.findIndex(r => r[pk] === row[pk]);
  if (i >= 0) rows[i] = { ...rows[i], ...row }; else rows.push(row);
  setTable(name, rows);
  return row;
};
const remove = (name, pk, id) => setTable(name, table(name).filter(r => r[pk] !== id));
const clone = (v) => JSON.parse(JSON.stringify(v));

/** 5) 핸들러들 */
export const handlers = [
  /* MAIN */
  ...paths("/forecast/series").map((p) =>
    http.get(p, ({ request }) => {
      const url = new URL(request.url);
      const h = Number(url.searchParams.get("h") || 12);
      const now = new Date();
      const series = Array.from({ length: h }, (_, k) => ({
        date: new Date(now.getFullYear(), now.getMonth() + k + 1, 1).toISOString().slice(0, 7),
        value: 100 + 5 * k + Math.round(Math.random() * 8),
      }));
      return HttpResponse.json({ itemNo: Number(url.searchParams.get("itemNo") || 1), series });
    })
  ),
  // 드롭다운: /plan/itemlist/main
  ...paths("/plan/itemlist/main").map((p) =>
    http.get(p, () => {
